var pad = 42;
var bMax = 0.995;
var kMax = 4.0;
var X = function (b) { return pad + (b / bMax) * (W - pad * 1.4); };
var Y = function (k) { return H - pad + 6 - (k / kMax) * (H - pad * 1.3); };

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.lineWidth = 1;

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(bMax), Y(0));
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(kMax));
ctx.stroke();

// gridline at K = mc^2
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(0), Y(1)); ctx.lineTo(X(bMax), Y(1)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText('K = mc2', X(0) + 6, Y(1) - 5);

// classical curve
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
for (var i = 0; i <= 200; i++) {
  var b1 = bMax * i / 200;
  var k1 = 0.5 * b1 * b1;
  if (k1 > kMax) break;
  i === 0 ? ctx.moveTo(X(b1), Y(k1)) : ctx.lineTo(X(b1), Y(k1));
}
ctx.stroke();

// relativistic curve
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
var started = false;
for (var j = 0; j <= 400; j++) {
  var b2 = bMax * j / 400;
  var k2 = 1 / Math.sqrt(1 - b2 * b2) - 1;
  if (k2 > kMax) break;
  started ? ctx.lineTo(X(b2), Y(k2)) : ctx.moveTo(X(b2), Y(k2));
  started = true;
}
ctx.stroke();

// marker at the slider speed
var b = p.beta;
var kr = 1 / Math.sqrt(1 - b * b) - 1;
var kc = 0.5 * b * b;
var krPlot = Math.min(kr, kMax);
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 3]);
ctx.beginPath(); ctx.moveTo(X(b), Y(0)); ctx.lineTo(X(b), Y(krPlot)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(b), Y(Math.min(kc, kMax)), 4, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(b), Y(krPlot), 4.5, 0, Math.PI * 2); ctx.fill();

// labels
ctx.fillStyle = C.ink;
ctx.fillText('K / mc2', 6, Y(kMax) - 8);
ctx.fillText('v / c', X(bMax) - 26, Y(0) + 18);
ctx.fillText('0', X(0) - 10, Y(0) + 16);
ctx.fillText('1', X(1) - 12, Y(0) + 16);
ctx.fillStyle = C.accent;
ctx.fillText('true: (gamma - 1) mc2', X(0.10), Y(3.1));
ctx.fillStyle = C.figure;
ctx.fillText('classical: half m v squared', X(0.40), Y(0.62));

var ratio = 100 * kc / kr;
out.note = 'v/c = ' + b.toFixed(3) + ':  classical K = ' + kc.toFixed(3) + ' mc2, true K = ' + kr.toFixed(3) + ' mc2  (classical is ' + ratio.toFixed(1) + '% of true)';

var g = p.gamma;
var beta = Math.sqrt(Math.max(0, 1 - 1 / (g * g)));
var pc = g * beta;
var E = g;

var pad = 46;
var base = W - pad * 2.2;
var avail = H - pad * 1.6;
var sc = Math.min(base / 1.0, avail / Math.max(pc, 0.6));
sc = Math.min(sc, base);
var x0 = pad, y0 = H - pad;
var x1 = x0 + sc * 1.0;
var y1 = y0 - sc * pc;
if (y1 < 14) { sc = sc * (y0 - 14) / (y0 - y1); x1 = x0 + sc; y1 = y0 - sc * pc; }

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';

// legs
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y0); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x1, y0); ctx.lineTo(x1, y1); ctx.stroke();

// hypotenuse
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();

// right-angle mark
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
var s = 9;
ctx.beginPath();
ctx.moveTo(x1 - s, y0); ctx.lineTo(x1 - s, y0 - s); ctx.lineTo(x1, y0 - s);
ctx.stroke();

// labels
ctx.fillStyle = C.figure;
ctx.fillText('rest energy  mc2', x0 + 8, y0 + 18);
ctx.fillText('momentum  pc', x1 + 8, (y0 + y1) / 2);
ctx.fillStyle = C.accent;
ctx.fillText('total energy  E', x0 + 10, y1 + (y0 - y1) * 0.42 - 8);

ctx.fillStyle = C.ink;
ctx.fillText('E squared = (pc) squared + (mc2) squared', x0, 18);

out.note = 'gamma = ' + g.toFixed(2) + ',  v/c = ' + beta.toFixed(4) + ',  E = ' + E.toFixed(3) + ' mc2,  pc = ' + pc.toFixed(3) + ' mc2,  K = ' + (g - 1).toFixed(3) + ' mc2';

var g = p.gamma;
var b = Math.sqrt(Math.max(0, 1 - 1 / (g * g)));
var th = p.star * Math.PI / 180;
var m = 135.0;

var a1 = Math.atan2(Math.sin(th), g * (Math.cos(th) + b));
var a2 = Math.atan2(Math.sin(th), g * (-Math.cos(th) + b));
var open = (a1 + a2) * 180 / Math.PI;
var E1 = 0.5 * m * g * (1 + b * Math.cos(th));
var E2 = 0.5 * m * g * (1 - b * Math.cos(th));

var cx = W * 0.46, cy = H * 0.55;
var L = Math.min(W * 0.42, H * 0.40);

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.lineWidth = 1;

// flight axis
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(20, cy); ctx.lineTo(W - 14, cy); ctx.stroke();
ctx.setLineDash([]);

var cycle = 3.2;
var ph = (t % cycle) / cycle;

function arrow(x, y, dx, dy, col, wid) {
  ctx.strokeStyle = col; ctx.lineWidth = wid;
  ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + dx, y + dy); ctx.stroke();
  var len = Math.sqrt(dx * dx + dy * dy);
  if (len < 1) return;
  var ux = dx / len, uy = dy / len;
  ctx.beginPath();
  ctx.moveTo(x + dx, y + dy);
  ctx.lineTo(x + dx - 8 * ux + 4 * uy, y + dy - 8 * uy - 4 * ux);
  ctx.lineTo(x + dx - 8 * ux - 4 * uy, y + dy - 8 * uy + 4 * ux);
  ctx.closePath();
  ctx.fillStyle = col; ctx.fill();
}

if (ph < 0.45) {
  // incoming pion
  var frac = ph / 0.45;
  var px = 26 + (cx - 26) * frac;
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(px, cy, 7, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.fillText('pion, gamma = ' + g.toFixed(2), 24, cy - 16);
} else {
  var f2 = (ph - 0.45) / 0.55;
  ctx.fillStyle = C.faint;
  ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
  arrow(cx, cy, L * f2 * Math.cos(a1), -L * f2 * Math.sin(a1), C.accent, 2);
  arrow(cx, cy, L * f2 * Math.cos(a2), L * f2 * Math.sin(a2), C.figure, 2);
  ctx.fillStyle = C.accent;
  ctx.fillText(E1.toFixed(1) + ' MeV', cx + L * 0.72 * Math.cos(a1), cy - L * 0.72 * Math.sin(a1) - 8);
  ctx.fillStyle = C.figure;
  ctx.fillText(E2.toFixed(1) + ' MeV', cx + L * 0.72 * Math.cos(a2), cy + L * 0.72 * Math.sin(a2) + 16);
}

// opening-angle wedge
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(cx, cy, 34, -a1, a2); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(open.toFixed(2) + ' deg', cx + 40, cy + 4);
ctx.fillText('direction of flight', W - 130, cy - 10);

var minOpen = 2 * Math.asin(Math.min(1, 1 / g)) * 180 / Math.PI;
out.note = 'opening angle ' + open.toFixed(2) + ' deg;  smallest possible for this gamma is ' + minOpen.toFixed(2) + ' deg (emission sideways in the pion frame); photon energies ' + E1.toFixed(1) + ' and ' + E2.toFixed(1) + ' MeV';
